-- 集成测试数据：覆盖排序、筛选、facets、优选位、历史退役记录、不可用排除、IPv6 出口。
-- 由 tests/fixtures/generate_seed.py 生成，不要手工编辑。
-- 时间占位 __NOW2M__ 由 tests/fixtures/load.sh 在导入前替换成真实时间戳
-- （优选位判定要求连通性/出口证据在 45 分钟内，固定时间会随时间失效）。
BEGIN;
TRUNCATE node_explorer_node_registry, node_explorer_connectivity, node_explorer_exits, node_explorer_ip_attributes, node_explorer_service_status RESTART IDENTITY CASCADE;
UPDATE node_explorer_connectivity c SET payload=c.payload || jsonb_build_object('incarnation',n.incarnation,'configDigest',md5((n.node - 'rawLink' - 'generatedLink')::text)) FROM node_explorer_node_registry n WHERE n.identity=c.identity;
COMMIT;
